import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';

const Header = () => {
    const [isLoggedin, setIsLoggedin] = useState(false);
    const navigate = useNavigate();

    useEffect(() => {
        const session = sessionStorage.getItem('session');
        if (session) {
            setIsLoggedin(true);
        }
    }, []);

    const session = sessionStorage.getItem('session');
    const userData = session ? JSON.parse(session) : null;
    const handleAuthClick = () => {
        if (isLoggedin) {
            sessionStorage.removeItem('session');
            setIsLoggedin(false);
            navigate('/');
        } else {
            navigate('/');
        }
    };

    return (
        <header className="fixed top-0 min-w-[100%] z-50 flex justify-between items-center px-margin-mobile md:px-margin-desktop py-4 max-w-container-max mx-auto bg-surface dark:bg-surface-dim border-b border-outline-variant dark:border-outline">
            <div className="flex items-center cursor-pointer active:opacity-80">
                {!isLoggedin?<Link to="/" className="flex items-center gap-1 hover:no-underline">
                    <span className="material-symbols-outlined text-primary dark:text-primary-fixed" style={{ fontSize: '24px' }}>shield</span>
                    <span className="font-headline-md text-headline-md font-bold text-primary dark:text-primary-fixed !text-[24px]">TheEntrance</span>
                </Link>:<div className="flex items-center gap-1 hover:no-underline">
                    <span className="material-symbols-outlined text-primary dark:text-primary-fixed" style={{ fontSize: '24px' }}>shield</span> <span className="font-headline-md text-headline-md font-bold text-primary dark:text-primary-fixed !text-[24px]">TheEntrance</span></div>}
            </div>
            <div className="flex justify-center items-center gap-3">
                {isLoggedin && <span className='text-secondary font-bold dark:text-primary-fixed-container'>Hey {userData.first_name}!</span>}
                <button
                    className="px-6 py-2 bg-primary dark:bg-primary-fixed text-white font-semibold rounded-full shadow-sm hover:scale-105 hover:cursor-pointer  active:scale-95 transition-all duration-200 flex items-center justify-center"
                    onClick={handleAuthClick}
                >
                    {isLoggedin ? "Logout" : "Login"}
            </button>
            </div>
        </header>
    );
};

export default Header;
